// === Tab: frag.glsl ===
#version 300 es
/**********************/
/** Merry Christmas! **/
/**********************/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
#define FC gl_FragCoord.xy
#define R resolution
#define T (-.5+.6*time)
#define MN min(R.x,R.y)
#define hue(a) (.6+.6*cos(5.3*(a)+vec3(0,23,21)))
vec3 star(vec2 p) {
	vec2 q=p;
	p*=44.;
	p=vec2(atan(p.x,p.y),length(p));
	p.y+=.2*floor(cos(p.x*6.)*15.);
	p.y+=.1*floor(cos(p.x*30.)*10.);
	p=vec2(p.y*cos(p.x),p.y*sin(p.x));
	float d=length(p);
	return 1./d*hue(length(q)-T);
}
float tri(vec2 p, vec2 s) {
	p.x=abs(p.x);
	return max(-p.y-s.y,dot(p,vec2(1.7,.7))-s.x);
}
vec3 tree(vec2 p, float k) {
	vec2 q=p;
	p.x=abs(p.x)-sin(p.y*88.)*5e-3;
	p.y-=sin(q.x*77.)*5e-3;
	float d=tri(p+vec2(0,.2),vec2(.25,.5));
	return (3e-3*(1.+k))/abs(d)*hue(length(p)+T);
}
void main(void) {
	vec2 uv=(FC-.5*R)/MN;
	if (R.x>R.y*.5) uv*=2.;
	vec2 p=uv;
	vec3 col=vec3(0);
	for (float i=.0; i<5.; i++) {
		p*=vec2(1.+i*min(1.,(1.-log(i))),1.-i*.01);
		col+=tree(p-vec2(0,i*.02),i);
	}
	col=max(col,star(uv-vec2(0,.5)));
	col=max(col,.08);
	O=vec4(col,1);
}

